#include <cstdio>
#include <vector>
#include <climits>

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    std::vector<int> a(n);
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);

    const int INF = INT_MAX / 2;
    std::vector<int> b(n);

    // Passagem da esquerda para a direita:
    // b[i] = min(A_i se conhecido, b[i-1] + 1)
    for (int i = 0; i < n; i++) {
        b[i] = (a[i] == -1) ? INF : a[i];
        if (i > 0 && b[i - 1] + 1 < b[i]) b[i] = b[i - 1] + 1;
    }

    // Passagem da direita para a esquerda:
    // b[i] = min(b[i], b[i+1] + 1)
    for (int i = n - 2; i >= 0; i--) {
        if (b[i + 1] + 1 < b[i]) b[i] = b[i + 1] + 1;
    }

    // Agora b[i] = min sobre todo degrau conhecido j de (A_j + |i - j|),
    // que é a maior altura possível do degrau i (o "cone" inferior é uma
    // reconstrução válida que atinge esse valor em cada posição).
    for (int i = 0; i < n; i++) {
        if (i + 1 < n) printf("%d ", b[i]);
        else printf("%d\n", b[i]);
    }

    return 0;
}
